mapper.select:
SELECT b.*, bt.type_code, bt.type_name, m.name AS member_name FROM board b LEFT JOIN board_type bt ON b.board_type_id = bt.board_type_id LEFT JOIN member m ON b.member_id = m.member_id
AND b.status != 'DELETED'
AND bt.type_code = #{typeCode}
AND (b.title LIKE CONCAT('%', #{keyword}, '%') OR b.content LIKE CONCAT('%', #{keyword}, '%'))
AND b.title LIKE CONCAT('%', #{title}, '%')
AND b.is_pinned = #{isPinned}
ORDER BY b.is_pinned DESC, b.created_at DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM board b LEFT JOIN board_type bt ON b.board_type_id = bt.board_type_id
AND b.status != 'DELETED'
AND bt.type_code = #{typeCode}
AND (b.title LIKE CONCAT('%', #{keyword}, '%') OR b.content LIKE CONCAT('%', #{keyword}, '%'))
AND b.title LIKE CONCAT('%', #{title}, '%')
AND b.is_pinned = #{isPinned}

mapper.update:
UPDATE board
title = #{dto.title}, content = #{dto.content}, thumbnail = #{dto.thumbnail}, source = #{dto.source}, source_url = #{dto.sourceUrl}, is_pinned = #{dto.isPinned}, is_active = #{dto.isActive},
WHERE board_id = #{boardId}

mapper.select:
SELECT * FROM common_file
WHERE ref_type = #{refType}
  AND ref_id   = #{refId}
  AND is_active = 1
ORDER BY sort_order ASC
